"""Drift check: freshly generated bytes must equal the committed files in `generated/`."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True, slots=True)
class DriftReport:
    changed: tuple[str, ...]
    missing: tuple[str, ...]

    @property
    def ok(self) -> bool:
        return not self.changed and not self.missing


class DriftChecker:
    def __init__(self, directory: Path) -> None:
        self._directory = directory

    def check(self, files: Mapping[str, str]) -> DriftReport:
        changed: list[str] = []
        missing: list[str] = []
        for name, text in sorted(files.items()):
            path = self._directory / name
            if not path.exists():
                missing.append(name)
            elif path.read_bytes() != text.encode("utf-8"):
                changed.append(name)
        return DriftReport(tuple(changed), tuple(missing))
